+/**
+ * 根据紫外线指数给出防护建议。
+ *
+ * @param {number} uv 紫外线指数，应为非负有限数值
+ * @returns {'弱' | '中等' | '强' | '极强' | null} 对应等级，非法输入返回 null
+ */
+export function uvAdvice(uv) {
+  if (typeof uv !== 'number' || !Number.isFinite(uv) || uv < 0) return null;
+  if (uv <= 2) return '弱';
+  if (uv <= 5) return '中等';
+  if (uv <= 7) return '强';
+  return '极强';
+}
